using System;
using System.Reflection;
using System.Threading;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

[AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
public sealed class TimedTestMethodAttribute : Attribute
{
    public int WarningThresholdMs { get; }

    public TimedTestMethodAttribute(int warningThresholdMs = 5000)
    {
        WarningThresholdMs = warningThresholdMs;
    }
}

public class TimedTestMethodFixture : IDisposable
{
    private readonly System.Diagnostics.Stopwatch _sw = System.Diagnostics.Stopwatch.StartNew();
    private readonly string _testName;
    private readonly int _warningThresholdMs;

    public TimedTestMethodFixture(TestContext testContext)
    {
        _testName = testContext.TestName ?? "Unknown";

        var method = testContext.GetType().Assembly
            .GetTypes()
            .SelectMany(t => t.GetMethods())
            .FirstOrDefault(m => m.Name == _testName);

        var attr = method?.GetCustomAttribute<TimedTestMethodAttribute>();
        _warningThresholdMs = attr?.WarningThresholdMs ?? 5000;
    }

    public void Dispose()
    {
        _sw.Stop();
        if (_sw.ElapsedMilliseconds > _warningThresholdMs)
        {
            Console.WriteLine($"WARNING: {_testName} took {_sw.ElapsedMilliseconds}ms (threshold: {_warningThresholdMs}ms)");
        }
    }
}

